<?php declare(strict_types=1);
function admin_badge(string $status): string { $labels=['ativo'=>'Ativa','pendente'=>'Pendente','inativo'=>'Inativa','bloqueado'=>'Bloqueada']; return '<span class="admin-badge admin-badge-'.admin_h($status).'">'.admin_h($labels[$status]??$status).'</span>'; }
function admin_empty(string $title,string $text): void { echo '<div class="admin-empty"><i class="bi bi-inbox"></i><strong>'.admin_h($title).'</strong><p>'.admin_h($text).'</p></div>'; }
function admin_pagination(int $page,int $total,int $perPage,string $path,array $query=[]): void { $pages=max(1,(int)ceil($total/$perPage)); if($pages<2)return; $start=max(1,$page-2);$end=min($pages,$page+2);echo '<nav class="admin-pagination" aria-label="Paginação">';if($page>1){$query['page']=$page-1;echo '<a href="'.admin_url($path.'?'.http_build_query($query)).'" aria-label="Página anterior">Anterior</a>';}for($i=$start;$i<=$end;$i++){$query['page']=$i;echo '<a class="'.($i===$page?'active':'').'" '.($i===$page?'aria-current="page"':'').' href="'.admin_url($path.'?'.http_build_query($query)).'">'.$i.'</a>';}if($page<$pages){$query['page']=$page+1;echo '<a href="'.admin_url($path.'?'.http_build_query($query)).'" aria-label="Próxima página">Próxima</a>';}echo '</nav>'; }
